class Solution { private List<Integer> occurrences(String text,String pattern){int[] prefix=new int[pattern.length()];for(int i=1,matched=0;i<pattern.length();i++){while(matched>0&&pattern.charAt(i)!=pattern.charAt(matched))matched=prefix[matched-1];if(pattern.charAt(i)==pattern.charAt(matched))matched++;prefix[i]=matched;}List<Integer> positions=new ArrayList<>();for(int i=0,matched=0;i<text.length();i++){while(matched>0&&text.charAt(i)!=pattern.charAt(matched))matched=prefix[matched-1];if(text.charAt(i)==pattern.charAt(matched))matched++;if(matched==pattern.length()){positions.add(i-pattern.length()+1);matched=prefix[matched-1];}}return positions;}public List<Integer> beautifulIndices(String s,String a,String b,int k){List<Integer> first=occurrences(s,a),second=occurrences(s,b),answer=new ArrayList<>();int pointer=0;for(int index:first){while(pointer<second.size()&&second.get(pointer)<index-k)pointer++;if(pointer<second.size()&&second.get(pointer)<=index+k)answer.add(index);}return answer;} }
